func proxyHandler(w http.ResponseWriter, r *http.Request) {
	target := r.URL.Query().Get("url")
	resp, err := http.Get(target)
	if err != nil {
		http.Error(w, "fetch failed", http.StatusBadGateway)
		return
	}
	defer resp.Body.Close()
	w.Header().Set("Content-Type", resp.Header.Get("Content-Type"))
	io.Copy(w, io.LimitReader(resp.Body, 1<<20))
}

server.createContext("/fetch", exchange -> {
    String query = exchange.getRequestURI().getQuery();
    String target = URLDecoder.decode(query.substring("u=".length()), StandardCharsets.UTF_8);
    HttpRequest req = HttpRequest.newBuilder(URI.create(target)).GET().build();
    try {
        HttpResponse<byte[]> resp = client.send(req, HttpResponse.BodyHandlers.ofByteArray());
        exchange.sendResponseHeaders(200, resp.body().length);
        exchange.getResponseBody().write(resp.body());
    } catch (InterruptedException e) {
        exchange.sendResponseHeaders(504, -1);
    }
    exchange.close();
});

