def parse_overrides(args):
    overrides = {}
    for arg in args:
        key, _, raw = arg.partition("=")
        try:
            overrides[key] = ast.literal_eval(raw)
        except (ValueError, SyntaxError):
            overrides[key] = raw
    return overrides

