class PasswordService(private val argon2: Argon2 = Argon2Factory.create(Argon2Types.ARGON2id)) {
    fun hash(password: CharArray): String =
        try {
            argon2.hash(3, 65_536, 1, password)
        } finally {
            argon2.wipeArray(password)
        }

    fun verify(stored: String, attempt: CharArray): Boolean =
        try {
            argon2.verify(stored, attempt)
        } finally {
            argon2.wipeArray(attempt)
        }
}

int count_by_status(sqlite3 *db, const char *status) {
    sqlite3_stmt *stmt;
    int count = -1;
    if (sqlite3_prepare_v2(db, "SELECT COUNT(*) FROM tickets WHERE status = ?1", -1, &stmt, NULL) != SQLITE_OK)
        return -1;
    sqlite3_bind_text(stmt, 1, status, -1, SQLITE_TRANSIENT);
    if (sqlite3_step(stmt) == SQLITE_ROW)
        count = sqlite3_column_int(stmt, 0);
    sqlite3_finalize(stmt);
    return count;
}
